import { useLayoutEffect, useState, useCallback } from "react";
import { debounce } from "lodash-es";

export const useVisibleTabBar = (
  containerRef: React.RefObject<HTMLElement>,
  allValues: string[],
  moreButtonRef: React.RefObject<HTMLElement>,
) => {
  const [visibleCount, setVisibleCount] = useState<number>(Infinity);

  const measure = useCallback(() => {
    const container = containerRef.current;
    if (!container) return;

    const moreButtonWidth = moreButtonRef.current?.getBoundingClientRect().width ?? 0;
    const tabElements = Array.from(
      container.querySelectorAll<HTMLElement>(`[data-value]:not([data-value="more"])`),
    );

    const gap = parseFloat(window.getComputedStyle(container).gap) || 0;
    const availableWidth = container.offsetWidth;
    let totalWidth = 0;
    let newVisibleCount = 0;

    for (const tabElement of tabElements) {
      const tabWidth = tabElement.getBoundingClientRect().width;
      if (totalWidth + tabWidth + gap > availableWidth - moreButtonWidth) {
        break;
      }
      totalWidth += tabWidth + gap;
      newVisibleCount++;
    }

    setVisibleCount(newVisibleCount);
  }, [containerRef, moreButtonRef]);

  useLayoutEffect(() => {
    const container = containerRef.current;
    if (!container) return;

    const debouncedMeasure = debounce(measure, 0);
    const observer = new ResizeObserver(debouncedMeasure);

    observer.observe(container);
    if (moreButtonRef.current) {
      observer.observe(moreButtonRef.current);
    }

    // Initial measure after first render
    debouncedMeasure();

    return () => {
      observer.disconnect();
    };
  }, [measure, containerRef, moreButtonRef, allValues]);

  const visibleValues = allValues.slice(0, visibleCount);
  const overflowValues = allValues.slice(visibleCount);

  return { visibleValues, overflowValues };
};
